Author: phongpham
Description: Certificate Services denied a certificate request
EventId: 4888
Channel: Security
Provider: Microsoft-Windows-Security-Auditing

Maps:
  -
    Property: UserName
    PropertyValue: "%Requester%"
    Values:
      -
        Name: Requester
        Value: "/Event/EventData/Data[@Name=\"Requester\"]"
  -
    Property: PayloadData1
    PropertyValue: "%Attributes%"
    Values:
      -
        Name: Attributes
        Value: "/Event/EventData/Data[@Name=\"Attributes\"]"
  -
    Property: PayloadData2
    PropertyValue: "Subject Key Identifier: %SubjectKeyIdentifier%"
    Values:
      -
        Name: SubjectKeyIdentifier
        Value: "/Event/EventData/Data[@Name=\"SubjectKeyIdentifier\"]"